float noise4 (vec2 uvi) { float n1,n2,n3,n4,zv; zv = 0.006*uTime;
n1 = lum(texture(sampler_noise_hq, (uvi)));
n2 = lum(texture(sampler_noise_hq, (uvi * 2.0+zv)));
n3 = lum(texture(sampler_noise_hq, (uvi * 4.0+zv)));
n4 = lum(texture(sampler_noise_hq, (uvi * 8.0+4*zv)));
return n1 + n2 / 2.0 + n3 / 4.0 + n4 / 8.0;}
float noise3 (vec3 uvi) {float arg;
return  clamp(texture(sampler_noise_hq,uvi.xy / 16.0)-.5,-.25,.25) * 2.0
+(texture(sampler_noise_hq,uvi.xy / 8.0)-.5) / 4.0
+(texture(sampler_noise_hq,(uvi.x + sin(2.0 * uvi.y)) / 2.0)) / 8.0;}
vec3 rs_lav (vec2 uvi, float berg) {  float z; vec2 rs;
z = 8.0 / (uvi.y)*(q8 - 4.0*berg); z = clamp(z,-8,100.0 * hordist); //#final check !
rs.x = uvi.x*z ; rs.y = z;
rs = multiply(rs,mat2(q3,q4,-q4,q3));
return vec3(rs / 64.0,z); }
vec3 rs_sky (vec2 uvi, float berg) {  float z; vec2 rs;
z = 8.0 / (uvi.y - berg-.5); z = clamp(z,-32, 1.0 );
rs.x = (uvi.x)*z ; rs.y = z;
rs = multiply(rs,mat2(q3,q4,-q4,q3));
return vec3(-rs / 64.0+mov / 512.0,z); }
